sys_script_include.script:
var AttendeeUtilss = Class.create();
AttendeeUtilss.prototype = {
    initialize: function() {
    },

    // a. Check if an attendee is registered by email
    isAttendeeRegistered: function(email) {
        var gr = new GlideRecord('x_1790116_event_ma_attendee');
        gr.addQuery('u_email', email);
        gr.query();
        if (gr.next()) {
            return 'Attendee is registered';
        }
        return 'Attendee not registered';
    },

    // b. Fetch attendee details by ID 
    getAttendeeByID: function(attendeeID) {
        var gr = new GlideRecord('x_1790116_event_ma_attendee');
        gr.addQuery('number', attendeeID);
        gr.query();
        if (gr.next()) {
            return gr.u_first_name + ' ' + gr.u_last_name + ' | ' + gr.u_email + ' | ' + gr.u_contact_number + ' | ' + gr.u_event_id.getDisplayValue();
        }
        return 'Attendee not found';
    },

    // c. Fetch all attendees for a specific event
    getAttendeesByEvent: function(eventID) {
        var gr = new GlideRecord('x_1790116_event_ma_attendee');
        gr.addQuery('u_event_id.number', eventID);
        gr.query();
        var result = [];
        while (gr.next()) {
            result.push(gr.u_first_name + ' ' + gr.u_last_name + ' | ' + gr.u_email);
        }
        return result.length ? result.join('\n') : 'No attendees found for this event';
    },

    type: 'AttendeeUtilss'
};
